+// DefaultOpenAIModel is used when the user selects the OpenAI-compatible provider
+// without an explicit model.
+const DefaultOpenAIModel = "gpt-4.1-mini"
+
+// OpenAICompatibleGenerator generates summaries via an OpenAI-compatible chat completions API.
+type OpenAICompatibleGenerator struct {
+	BaseURL    string
+	Model      string
+	APIKey     string
+	HTTPClient *http.Client
+}
+
+type openAIChatCompletionsRequest struct {
+	Model          string                `json:"model"`
+	Messages       []openAIMessage       `json:"messages"`
+	ResponseFormat *openAIResponseFormat `json:"response_format,omitempty"`
+}
+
+type openAIResponseFormat struct {
+	Type string `json:"type"`
+}
+
+type openAIMessage struct {
+	Role    string `json:"role"`
+	Content string `json:"content"`
+}
+
+type openAIChatCompletionsResponse struct {
+	Choices []struct {
+		Message openAIMessage `json:"message"`
+	} `json:"choices"`
+	Error *struct {
+		Message string `json:"message"`
+		Type    string `json:"type"`
+	} `json:"error,omitempty"`
+}
+
+// Generate creates a summary from checkpoint data using an OpenAI-compatible API.
+func (g *OpenAICompatibleGenerator) Generate(ctx context.Context, input Input) (*checkpoint.Summary, error) {
+	apiKey := g.APIKey
+	if apiKey == "" {
+		return nil, fmt.Errorf("summarization API key is not configured")
+	}
+
+	baseURL := strings.TrimRight(g.BaseURL, "/")
+	if baseURL == "" {
+		baseURL = "https://api.openai.com/v1"
+	}
+
+	model := g.Model
+	if model == "" {
+		model = DefaultOpenAIModel
+	}
+
+	requestBody := openAIChatCompletionsRequest{
+		Model: model,
+		Messages: []openAIMessage{
+			{
+				Role:    "user",
+				Content: buildSummarizationPrompt(FormatCondensedTranscript(input)),
+			},
+		},
+		ResponseFormat: &openAIResponseFormat{Type: "json_object"},
+	}
+
+	body, err := json.Marshal(requestBody)
+	if err != nil {
+		return nil, fmt.Errorf("failed to marshal summarize request: %w", err)
+	}
+
+	req, err := http.NewRequestWithContext(ctx, http.MethodPost, baseURL+"/chat/completions", bytes.NewReader(body))
+	if err != nil {
+		return nil, fmt.Errorf("failed to build summarize request: %w", err)
+	}
+	req.Header.Set("Authorization", "Bearer "+apiKey)
+	req.Header.Set("Content-Type", "application/json")
+
+	client := g.HTTPClient
+	if client == nil {
+		client = http.DefaultClient
+	}
+
+	resp, err := client.Do(req)
+	if err != nil {
+		return nil, fmt.Errorf("openai-compatible summarize request failed: %w", err)
+	}
+	defer resp.Body.Close()
+
+	responseBody, err := io.ReadAll(resp.Body)
+	if err != nil {
+		return nil, fmt.Errorf("failed to read summarize response: %w", err)
+	}
+
+	var parsed openAIChatCompletionsResponse
+	if err := json.Unmarshal(responseBody, &parsed); err != nil {
+		return nil, fmt.Errorf("failed to parse summarize response: %w", err)
+	}
+
+	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
+		if parsed.Error != nil && parsed.Error.Message != "" {
+			return nil, fmt.Errorf("openai-compatible summarize API failed (%d): %s", resp.StatusCode, parsed.Error.Message)
+		}
+		return nil, fmt.Errorf("openai-compatible summarize API failed (%d)", resp.StatusCode)
+	}
+
+	if len(parsed.Choices) == 0 || parsed.Choices[0].Message.Content == "" {
+		return nil, fmt.Errorf("openai-compatible summarize API returned no content")
+	}
+
+	resultJSON := extractJSONFromMarkdown(parsed.Choices[0].Message.Content)
+
+	var summary checkpoint.Summary
+	if err := json.Unmarshal([]byte(resultJSON), &summary); err != nil {
+		return nil, fmt.Errorf("failed to parse summary JSON: %w", err)
+	}
+
+	return &summary, nil
+}
+
+func apiKeyFromEnv(envVar string) string {
+	if envVar == "" {
+		return ""
+	}
+	return strings.TrimSpace(os.Getenv(envVar))
+}
